/**
 ******************************************************************************
 * @file    test_fx_queue.c
 * TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Jack's storage subsystem (best-ui), with an AI coding assistant;
 *          Brendon (integrator) made effect-file jobs resumable (30 Oct 2026, with an AI coding assistant).
 * @brief   Host tests for fx_queue.c: the order in which effect files are made.
 *
 * Groups:
 *   1. Touch: front of the list, a fifth name drops the last, a touch makes
 *      a name be checked again and forgets its cached source facts
 *   2. Next: the selected effect first, then cheapest first; checked pairs
 *      are skipped; an empty list has no next pair
 *   3. Mark: all six marked or mark_all makes a name leave; forget; clear
 *      (a new card) keeps the selected effect; a mark of a name no longer
 *      listed changes nothing
 *   4. No lock slot: the pair is tried once more, then marked
 *   5. Is a pair queued: listed and not checked (fx_job.c asks it for a
 *      parked job that can carry on exactly)
 * Pure logic: no card, no fake needed.
 ******************************************************************************/
#include "unity.h"
#include "fx_queue.h"
#include <string.h>

static fx_queue_t q;

void setUp(void)
{
    fxq_init(&q);
}

void tearDown(void) {}

/* The next pair, as "NAME/effect" checks. */
static void expect_next(const char *name, uint8_t effect)
{
    char got_name[FXS_NAME_LEN];
    uint8_t got_effect = 0U;
    TEST_ASSERT_TRUE(fxq_next(&q, got_name, &got_effect));
    TEST_ASSERT_EQUAL_STRING(name, got_name);
    TEST_ASSERT_EQUAL_UINT8(effect, got_effect);
}

/* ---------- 1. Touch ---------- */

void test_touch_adds_a_name_to_the_front(void)
{
    fxq_touch(&q, "REC01.WAV");
    fxq_touch(&q, "REC02.WAV");
    TEST_ASSERT_EQUAL_UINT8(2U, q.count);
    TEST_ASSERT_EQUAL_STRING("REC02.WAV", q.entry[0].name);
    TEST_ASSERT_EQUAL_STRING("REC01.WAV", q.entry[1].name);
}

void test_touch_moves_a_listed_name_to_the_front(void)
{
    fxq_touch(&q, "REC01.WAV");
    fxq_touch(&q, "REC02.WAV");
    fxq_touch(&q, "REC03.WAV");
    fxq_touch(&q, "REC01.WAV");
    TEST_ASSERT_EQUAL_UINT8(3U, q.count);
    TEST_ASSERT_EQUAL_STRING("REC01.WAV", q.entry[0].name);
    TEST_ASSERT_EQUAL_STRING("REC03.WAV", q.entry[1].name);
    TEST_ASSERT_EQUAL_STRING("REC02.WAV", q.entry[2].name);
}

void test_a_fifth_name_drops_the_least_urgent(void)
{
    fxq_touch(&q, "REC01.WAV");
    fxq_touch(&q, "REC02.WAV");
    fxq_touch(&q, "REC03.WAV");
    fxq_touch(&q, "REC04.WAV");
    fxq_touch(&q, "REC05.WAV");
    TEST_ASSERT_EQUAL_UINT8(FXQ_MAX_NAMES, q.count);
    TEST_ASSERT_EQUAL_STRING("REC05.WAV", q.entry[0].name);
    TEST_ASSERT_EQUAL_STRING("REC02.WAV", q.entry[3].name);     /* REC01 is gone */
}

void test_touch_clears_the_checked_effects_and_the_cached_facts(void)
{
    fxq_touch(&q, "REC01.WAV");
    fx_src_t src;
    memset(&src, 0, sizeof(src));
    src.size = 1234U;
    fxq_set_src(&q, "REC01.WAV", &src);
    fxq_mark(&q, "REC01.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_TRUE(fxq_get_src(&q, "REC01.WAV", &src));

    /* REC01 recorded again: every effect must be checked against the new file. */
    fxq_touch(&q, "REC01.WAV");
    TEST_ASSERT_FALSE(fxq_get_src(&q, "REC01.WAV", &src));
    expect_next("REC01.WAV", FXS_EFFECT_ECHO);
}

/* ---------- 2. Next ---------- */

void test_next_starts_at_the_selected_effect(void)
{
    fxq_select(&q, FXS_EFFECT_AUTOTUNE);
    fxq_touch(&q, "REC01.WAV");
    expect_next("REC01.WAV", FXS_EFFECT_AUTOTUNE);
    fxq_mark(&q, "REC01.WAV", FXS_EFFECT_AUTOTUNE);
    expect_next("REC01.WAV", FXS_EFFECT_ECHO);                   /* then the cheapest */
}

void test_with_none_selected_the_cheapest_go_first(void)
{
    static const uint8_t order[FXS_EFFECT_COUNT] = {
        FXS_EFFECT_ECHO, FXS_EFFECT_ROBOT, FXS_EFFECT_PITCHUP,
        FXS_EFFECT_PITCHDN, FXS_EFFECT_REVERB, FXS_EFFECT_AUTOTUNE
    };
    fxq_select(&q, FXS_EFFECT_NONE);
    fxq_touch(&q, "REC01.WAV");
    for (uint8_t i = 0U; i < FXS_EFFECT_COUNT; i++)
    {
        expect_next("REC01.WAV", order[i]);
        fxq_mark(&q, "REC01.WAV", order[i]);
    }
}

void test_next_skips_checked_pairs(void)
{
    fxq_touch(&q, "REC01.WAV");
    fxq_mark(&q, "REC01.WAV", FXS_EFFECT_ECHO);
    fxq_mark(&q, "REC01.WAV", FXS_EFFECT_ROBOT);
    expect_next("REC01.WAV", FXS_EFFECT_PITCHUP);
}

void test_the_front_name_is_finished_before_the_next_one(void)
{
    fxq_select(&q, FXS_EFFECT_REVERB);
    fxq_touch(&q, "REC01.WAV");
    fxq_touch(&q, "REC02.WAV");
    expect_next("REC02.WAV", FXS_EFFECT_REVERB);
    fxq_mark_all(&q, "REC02.WAV");
    expect_next("REC01.WAV", FXS_EFFECT_REVERB);                 /* the selected effect in every name */
}

void test_an_empty_list_has_no_next_pair(void)
{
    char name[FXS_NAME_LEN];
    uint8_t effect = 0U;
    TEST_ASSERT_FALSE(fxq_next(&q, name, &effect));
}

/* ---------- 3. Mark ---------- */

void test_a_name_leaves_when_all_six_are_checked(void)
{
    fxq_touch(&q, "REC01.WAV");
    for (uint8_t e = 1U; e <= FXS_EFFECT_COUNT; e++)
    {
        fxq_mark(&q, "REC01.WAV", e);
    }
    TEST_ASSERT_EQUAL_UINT8(0U, q.count);
}

void test_mark_all_makes_a_name_leave(void)
{
    fxq_touch(&q, "REC01.WAV");
    fxq_touch(&q, "BAD.WAV");
    fxq_mark_all(&q, "BAD.WAV");                    /* not a WAV Jack can make effects of */
    TEST_ASSERT_EQUAL_UINT8(1U, q.count);
    expect_next("REC01.WAV", FXS_EFFECT_ECHO);
}

void test_forget_removes_a_name(void)
{
    fxq_touch(&q, "REC01.WAV");
    fxq_touch(&q, "REC02.WAV");
    fxq_forget(&q, "REC02.WAV");
    TEST_ASSERT_EQUAL_UINT8(1U, q.count);
    TEST_ASSERT_EQUAL_STRING("REC01.WAV", q.entry[0].name);
}

void test_clear_empties_the_list_but_keeps_the_selected_effect(void)
{
    fxq_select(&q, FXS_EFFECT_ROBOT);
    fxq_touch(&q, "REC01.WAV");
    fxq_touch(&q, "REC02.WAV");
    fxq_clear(&q);                                  /* a new card: the old names go */
    TEST_ASSERT_EQUAL_UINT8(0U, q.count);
    TEST_ASSERT_EQUAL_UINT8(FXS_EFFECT_ROBOT, q.selected);
    fxq_touch(&q, "REC03.WAV");
    expect_next("REC03.WAV", FXS_EFFECT_ROBOT);     /* the user's effect still comes first */
}

void test_a_mark_of_a_name_no_longer_listed_is_ignored(void)
{
    fxq_touch(&q, "REC01.WAV");
    fxq_touch(&q, "REC02.WAV");
    fxq_touch(&q, "REC03.WAV");
    fxq_touch(&q, "REC04.WAV");
    fxq_touch(&q, "REC05.WAV");                     /* REC01 pushed out */
    fxq_mark(&q, "REC01.WAV", FXS_EFFECT_ECHO);
    fxq_mark_all(&q, "REC01.WAV");
    TEST_ASSERT_EQUAL_UINT8(FXQ_MAX_NAMES, q.count);
    for (uint8_t i = 0U; i < q.count; i++)
    {
        TEST_ASSERT_TRUE(strcmp(q.entry[i].name, "REC01.WAV") != 0);   /* never added back */
    }
    fxq_forget(&q, "REC02.WAV");
    fxq_mark(&q, "REC02.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_EQUAL_UINT8(FXQ_MAX_NAMES - 1U, q.count);
}

/* ---------- 4. No lock slot ---------- */

void test_no_slot_keeps_the_pair_queued_once(void)
{
    fxq_touch(&q, "REC01.WAV");
    TEST_ASSERT_TRUE(fxq_no_slot(&q, "REC01.WAV", FXS_EFFECT_ECHO));    /* first time: try again */
    expect_next("REC01.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_FALSE(fxq_no_slot(&q, "REC01.WAV", FXS_EFFECT_ECHO));   /* again in a row: give up */
    TEST_ASSERT_FALSE(fxq_no_slot(&q, "NOPE.WAV", FXS_EFFECT_ECHO));    /* not listed: nothing to keep */
}

/* ---------- 5. Is a pair queued (TEAM CODE, written by Brendon, 30 Oct 2026) ---------- */

void test_a_pair_is_queued_while_listed_and_not_checked(void)
{
    TEST_ASSERT_FALSE(fxq_is_queued(&q, "REC01.WAV", FXS_EFFECT_ECHO));     /* not listed */
    fxq_touch(&q, "REC01.WAV");
    TEST_ASSERT_TRUE(fxq_is_queued(&q, "REC01.WAV", FXS_EFFECT_ECHO));
    TEST_ASSERT_FALSE(fxq_is_queued(&q, "REC01.WAV", FXS_EFFECT_NONE));     /* no such effect */
    fxq_mark(&q, "REC01.WAV", FXS_EFFECT_ECHO);
    TEST_ASSERT_FALSE(fxq_is_queued(&q, "REC01.WAV", FXS_EFFECT_ECHO));     /* done */
    TEST_ASSERT_TRUE(fxq_is_queued(&q, "REC01.WAV", FXS_EFFECT_AUTOTUNE));
    fxq_touch(&q, "REC01.WAV");
    TEST_ASSERT_TRUE(fxq_is_queued(&q, "REC01.WAV", FXS_EFFECT_ECHO));      /* a touch: checked again */
    fxq_forget(&q, "REC01.WAV");
    TEST_ASSERT_FALSE(fxq_is_queued(&q, "REC01.WAV", FXS_EFFECT_AUTOTUNE));
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_touch_adds_a_name_to_the_front);
    RUN_TEST(test_touch_moves_a_listed_name_to_the_front);
    RUN_TEST(test_a_fifth_name_drops_the_least_urgent);
    RUN_TEST(test_touch_clears_the_checked_effects_and_the_cached_facts);
    RUN_TEST(test_next_starts_at_the_selected_effect);
    RUN_TEST(test_with_none_selected_the_cheapest_go_first);
    RUN_TEST(test_next_skips_checked_pairs);
    RUN_TEST(test_the_front_name_is_finished_before_the_next_one);
    RUN_TEST(test_an_empty_list_has_no_next_pair);
    RUN_TEST(test_a_name_leaves_when_all_six_are_checked);
    RUN_TEST(test_mark_all_makes_a_name_leave);
    RUN_TEST(test_forget_removes_a_name);
    RUN_TEST(test_clear_empties_the_list_but_keeps_the_selected_effect);
    RUN_TEST(test_a_mark_of_a_name_no_longer_listed_is_ignored);
    RUN_TEST(test_no_slot_keeps_the_pair_queued_once);
    RUN_TEST(test_a_pair_is_queued_while_listed_and_not_checked);
    return UNITY_END();
}
